const companies = $input.all();
const requests = [];

for (const company of companies) {
  const searchTerm = company.json.name;
  const url = `https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi`;
  const params = new URLSearchParams({
    db: 'pubmed',
    term: `${searchTerm}[Affiliation] AND ("medical device"[MeSH Terms] OR "medical devices"[All Fields])`,
    retmode: 'json',
    retmax: '20',
    sort: 'date',
    mindate: '2024/01/01',
    datetype: 'pdat'
  });

  requests.push({
    company_id: company.json.id,
    company_name: searchTerm,
    url: `${url}?${params.toString()}`
  });
}

return requests.map(r => ({ json: r }));

const searchResult = $input.first().json;
const companyId = $node['Prepare PubMed Search'].json.company_id;
const pmids = searchResult.esearchresult?.idlist || [];

if (pmids.length === 0) {
  return [];
}

const fetchUrl = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi';
const params = new URLSearchParams({
  db: 'pubmed',
  id: pmids.join(','),
  retmode: 'xml'
});

return [{
  json: {
    company_id: companyId,
    pmids: pmids,
    url: `${fetchUrl}?${params.toString()}`
  }
}];

// Simplified XML parsing - use proper XML parser in production
const xmlData = $input.first().json.body || $input.first().json;
const companyId = $node['Prepare Details Fetch'].json.company_id;
const publications = [];

try {
  // Parse XML to extract publication data
  // This is simplified - use xml2js or similar library in production

  const pmidRegex = /<PMID[^>]*>(.*?)<\/PMID>/g;
  const titleRegex = /<ArticleTitle>(.*?)<\/ArticleTitle>/g;
  const abstractRegex = /<AbstractText>(.*?)<\/AbstractText>/gs;
  const journalRegex = /<Title>(.*?)<\/Title>/g;

  const pmids = [...xmlData.matchAll(pmidRegex)].map(m => m[1]);
  const titles = [...xmlData.matchAll(titleRegex)].map(m => m[1].replace(/<[^>]+>/g, ''));
  const abstracts = [...xmlData.matchAll(abstractRegex)].map(m => m[1].replace(/<[^>]+>/g, ''));
  const journals = [...xmlData.matchAll(journalRegex)].map(m => m[1]);

  for (let i = 0; i < pmids.length; i++) {
    publications.push({
      company_id: companyId,
      pmid: pmids[i],
      title: titles[i] || '',
      abstract: abstracts[i] || '',
      journal: journals[i] || '',
      publication_date: new Date().toISOString().split('T')[0],
      citation_count: 0,
      raw_data: JSON.stringify({ pmid: pmids[i] })
    });
  }
} catch (error) {
  console.error('XML parse error:', error.message);
}

return publications.map(p => ({ json: p }));
